-- Create "subscription_settings" table
CREATE TABLE "subscription_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "mail_subject" character varying NOT NULL DEFAULT '', "mail_body" text NULL, "digest_day" character varying NOT NULL DEFAULT '', PRIMARY KEY ("id"));
-- Create "subscription_notifications" table
CREATE TABLE "subscription_notifications" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "kind" character varying NOT NULL, "created_at" timestamptz NOT NULL, "read_at" timestamptz NULL, "mail_state" smallint NOT NULL DEFAULT 0, "user_id" bigint NOT NULL, "node_id" bigint NOT NULL, "comment_id" bigint NULL, "actor_id" bigint NULL, "term_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "subscription_notifications_users_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE, CONSTRAINT "subscription_notifications_nodes_node" FOREIGN KEY ("node_id") REFERENCES "nodes" ("id") ON DELETE CASCADE, CONSTRAINT "subscription_notifications_comments_comment" FOREIGN KEY ("comment_id") REFERENCES "comments" ("id") ON DELETE CASCADE, CONSTRAINT "subscription_notifications_users_actor" FOREIGN KEY ("actor_id") REFERENCES "users" ("id") ON DELETE SET NULL, CONSTRAINT "subscription_notifications_taxonomy_term_data_term" FOREIGN KEY ("term_id") REFERENCES "taxonomy_term_data" ("id") ON DELETE CASCADE);
-- Create index "idx_subscription_notifications_user" to table: "subscription_notifications"
CREATE INDEX "idx_subscription_notifications_user" ON "subscription_notifications" ("user_id", "read_at");
-- Create index "idx_subscription_notifications_mail" to table: "subscription_notifications"
CREATE INDEX "idx_subscription_notifications_mail" ON "subscription_notifications" ("mail_state", "user_id");
-- Create index "idx_subscription_notifications_created" to table: "subscription_notifications"
CREATE INDEX "idx_subscription_notifications_created" ON "subscription_notifications" ("created_at");
-- Create index "subscriptionnotification_actor_id" to table: "subscription_notifications"
CREATE INDEX "subscriptionnotification_actor_id" ON "subscription_notifications" ("actor_id");
-- Create index "subscriptionnotification_comment_id" to table: "subscription_notifications"
CREATE INDEX "subscriptionnotification_comment_id" ON "subscription_notifications" ("comment_id");
-- Create index "subscriptionnotification_node_id" to table: "subscription_notifications"
CREATE INDEX "subscriptionnotification_node_id" ON "subscription_notifications" ("node_id");
-- Create index "subscriptionnotification_term_id" to table: "subscription_notifications"
CREATE INDEX "subscriptionnotification_term_id" ON "subscription_notifications" ("term_id");
-- Create "subscription_user_settings" table
CREATE TABLE "subscription_user_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "mail" character varying NOT NULL DEFAULT 'now', "replies" boolean NOT NULL DEFAULT true, "auto_own" boolean NOT NULL DEFAULT true, "auto_commented" boolean NOT NULL DEFAULT true, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "subscription_user_settings_users_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE);
-- Create index "uk_subscription_user_settings_user" to table: "subscription_user_settings"
CREATE UNIQUE INDEX "uk_subscription_user_settings_user" ON "subscription_user_settings" ("user_id");
-- Create "subscriptions" table
CREATE TABLE "subscriptions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "muted" boolean NOT NULL DEFAULT false, "token" character varying NOT NULL, "created_at" timestamptz NOT NULL, "user_id" bigint NOT NULL, "node_id" bigint NULL, "term_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "subscriptions_users_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE, CONSTRAINT "subscriptions_nodes_node" FOREIGN KEY ("node_id") REFERENCES "nodes" ("id") ON DELETE CASCADE, CONSTRAINT "subscriptions_taxonomy_term_data_term" FOREIGN KEY ("term_id") REFERENCES "taxonomy_term_data" ("id") ON DELETE CASCADE);
-- Create index "uk_subscriptions_user_node" to table: "subscriptions"
CREATE UNIQUE INDEX "uk_subscriptions_user_node" ON "subscriptions" ("user_id", "node_id");
-- Create index "uk_subscriptions_user_term" to table: "subscriptions"
CREATE UNIQUE INDEX "uk_subscriptions_user_term" ON "subscriptions" ("user_id", "term_id");
-- Create index "idx_subscriptions_node" to table: "subscriptions"
CREATE INDEX "idx_subscriptions_node" ON "subscriptions" ("node_id", "muted");
-- Create index "idx_subscriptions_term" to table: "subscriptions"
CREATE INDEX "idx_subscriptions_term" ON "subscriptions" ("term_id", "muted");
-- Create index "uk_subscriptions_token" to table: "subscriptions"
CREATE UNIQUE INDEX "uk_subscriptions_token" ON "subscriptions" ("token");
